var n=`0394-sunday-roast`;var a=`world-0394`;var i=`GB`;var o=`northern-europe`;var r=4;var s=170;var u={en:`Sunday Roast`,ua:`Недільна печеня`};var l={en:`A Sunday roast of beef with root vegetables and gravy, served with horseradish.`,ua:`Недільна яловича печеня з коренеплодами та підливою, подається з хроном.`};var d=[{en:`Roast in a preheated 190°C oven for about 105 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 105 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:105,i:[[`beef-sirloin`,1200,`g`],[`extra-virgin-olive-oil`,55,`ml`],[`rosemary`,3,`sprig`],[`sea-salt`,12,`g`]]},{en:`Cut the vegetables evenly and roast at 200°C for about 55 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 55 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:55,i:[[`potato`,900,`g`],[`carrot`,450,`g`],[`duck-fat`,90,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`beef-stock`,380,`ml`],[`unsalted-butter`,45,`g`],[`all-purpose-flour`,40,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`horseradish-root`,60,`g`]]}];var g={slug:n,id:a,country:`GB`,region:o,servings:4,minutes:170,title:u,text:l,steps:d};export{i as country,g as default,a as id,s as minutes,o as region,r as servings,n as slug,d as steps,l as text,u as title};